class EventBus {
  #listeners = {};

  on(event, fn) {
    (this.#listeners[event] ??= []).push(fn);
    return () => this.off(event, fn);        // unsubscribe wapas do
  }

  off(event, fn) {
    this.#listeners[event] = (this.#listeners[event] || []).filter(f => f !== fn);
  }

  emit(event, data) {
    (this.#listeners[event] || []).forEach(fn => {
      try { fn(data); } catch (e) { console.error(e); }   // ek toote to baaki chalein
    });
  }
}

